def transform(grid):
    # Read each nonzero color block from left to right.
    colors = sorted({v for row in grid for v in row if v != 0},
                    key=lambda c: min(j for row in grid for j, v in enumerate(row) if v == c))
    objects = []
    for color in colors:
        cells = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == color]
        r0, r1 = min(i for i, j in cells), max(i for i, j in cells)
        c0, c1 = min(j for i, j in cells), max(j for i, j in cells)
        shape = [[grid[i][j] for j in range(c0, c1 + 1)] for i in range(r0, r1 + 1)]
        objects.append((shape, r1-r0+1, c1-c0+1))
    out = [[0 for _ in row] for row in grid]
    r = c = 0
    for idx, (shape, h, w) in enumerate(objects):
        for i in range(h):
            for j in range(w):
                if shape[i][j]:
                    rr, cc = r+i, c+j
                    if rr < len(out) and cc < len(out[0]):
                        out[rr][cc] = shape[i][j]
        if idx+1 < len(objects):
            r += h-1
            c += 1
    return out
